text(await tools.exec_command({cmd:"@'
import json,pathlib,hashlib
p=pathlib.Path('work/compact-caller')
def read(n): return json.loads((p/n).read_bytes())
def body(x): return x.get('structuredContent',x)
def ref(n):
 q=p/n
 return {'path':q.as_posix(),'sha256':hashlib.sha256(q.read_bytes()).hexdigest()}
c=read('compact.json'); receipt=body(read('receipt.json')); parent=body(read('parent-receipt.json'))
d=read('details.json'); f=body(read('refresh.json')); s=body(read('stale-recovery.json'))
assert c['path']==receipt['path']==parent['path']
assert c['sha256']==receipt['sha256']==parent['sha256']
h=pathlib.Path(c['path']); hb=h.read_bytes()
assert hashlib.sha256(hb).hexdigest()==c['sha256']
assert json.loads(hb)['details']==d
assert d['retained_specialist_observations']==json.loads(pathlib.Path('work/artistic-revision/SPECIALIST-RESULT.json').read_bytes())
checks={}
for name in ['details','resume']:
 loc=c[name+'_ref']; r=body(read(name+'-read.json'))
 exact=''.join(hb.decode().splitlines(keepends=True)[loc['start']-1:loc['end']])
 assert r['text']==exact
 assert len(exact.encode())==loc['bytes']
 checks[name]={'exact_slice':True,'trailing_member_comma':exact.rstrip().endswith(','),'bytes':loc['bytes']}
for r in [f,s]:
 assert r['requirements_hash']==c['requirements_hash']
 assert r['production']['continuation']['state_hash']==c['state_hash']
u=body(read('unknown-recovery.json')); ub=body(read('unknown-before.json'))
assert u==ub
job=next(j for j in u['jobs'] if j['id']=='member.job'); assert job['state']=='unknown'
assert not (p/'intentionally-missing.txt').exists()
errors={}; diagnostics={}
for name in ['invalid-authoring','stale-state','unavailable-observation','uncertain-remote','missing-capability']:
 x=read('errors/'+name+'.json')
 e=body(x['protocol_response']['result'] if name=='missing-capability' else x)
 errors[e['category']]=ref('errors/'+name+'.json')
